/**
 * Harness Client Protocol — the client half of UHP, without the HTTP.
 *
 * Everything here is the mechanics a UHP client has to get right no matter which server it talks
 * to: decoding the event stream, noticing a dropped event, assembling text out of deltas,
 * generating idempotency keys, and deciding whether a failure is worth retrying.
 *
 * There is no network code in this package. Give it bytes or events and it gives you facts.
 *
 * Spec: https://github.com/HarnessRouter/harnessrouter/tree/main/protocol
 */

import {
  EVENTS,
  TERMINAL_EVENTS,
  isRetryable,
  checkSequence,
} from 'unifiedharnessprotocol';

/**
 * Incremental Server-Sent Events decoder.
 *
 * Feed it chunks as they arrive; it returns the `data:` payloads that are complete. Partial
 * frames are held until the rest turns up, which is the entire reason this is a class and not a
 * function over a whole body.
 */
export class SseDecoder {
  #buffer = '';

  /** Push a chunk (string or Uint8Array) and get back the events that completed. */
  push(chunk) {
    this.#buffer += typeof chunk === 'string' ? chunk : new TextDecoder().decode(chunk, { stream: true });
    const events = [];
    let index;
    while ((index = this.#buffer.indexOf('\n\n')) !== -1) {
      const frame = this.#buffer.slice(0, index);
      this.#buffer = this.#buffer.slice(index + 2);
      const event = decodeFrame(frame);
      if (event !== undefined) events.push(event);
    }
    return events;
  }

  /** Whatever is left in the buffer, for a stream that ended without a trailing blank line. */
  flush() {
    const rest = this.#buffer;
    this.#buffer = '';
    const event = decodeFrame(rest);
    return event === undefined ? [] : [event];
  }
}

function decodeFrame(frame) {
  const data = frame
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trimStart())
    .join('\n');
  if (!data) return undefined; // keep-alive comments and empty frames are not events
  try {
    return JSON.parse(data);
  } catch {
    return undefined; // a server sending non-JSON is a finding, not a reason to throw mid-stream
  }
}

/**
 * Decode a `fetch` Response body into UHP events, in arrival order.
 *
 * ```js
 * for await (const event of readEventStream(response)) console.log(event.type);
 * ```
 */
export async function* readEventStream(response) {
  const body = response.body;
  if (!body) throw new Error('response has no body to stream');
  const decoder = new SseDecoder();
  for await (const chunk of body) {
    for (const event of decoder.push(chunk)) yield event;
  }
  for (const event of decoder.flush()) yield event;
}

/**
 * Accumulates a task's stream into the state a user interface actually needs.
 *
 * The stream is an optimisation; the stored response is the source of truth. This class is
 * written on that assumption — it will happily produce correct text from the terminal event
 * alone if every delta went missing.
 */
export class TaskAccumulator {
  constructor() {
    this.events = [];
    this.text = '';
    this.reasoning = '';
    this.toolCalls = [];
    this.annotations = [];
    this.response = null;
    this.error = null;
  }

  /** Feed one event. Returns the same event, so it can be dropped into a pipeline. */
  add(event) {
    if (!event || typeof event.type !== 'string') return event;
    this.events.push(event);
    switch (event.type) {
      case EVENTS.OUTPUT_TEXT_DELTA:
        this.text += event.delta ?? '';
        break;
      case EVENTS.REASONING_TEXT_DELTA:
        this.reasoning += event.delta ?? '';
        break;
      case EVENTS.ANNOTATION_ADDED:
        if (event.annotation) this.annotations.push(event.annotation);
        break;
      case EVENTS.OUTPUT_ITEM_DONE:
        if (event.item && event.item.type === 'function_call') this.toolCalls.push(event.item);
        break;
      case EVENTS.ERROR:
        this.error = { code: event.code, message: event.message, param: event.param ?? null };
        break;
      default:
        break;
    }
    if (TERMINAL_EVENTS.includes(event.type)) {
      this.response = event.response ?? null;
      if (this.response) {
        const fromResponse = outputText(this.response);
        if (fromResponse) this.text = fromResponse; // the terminal event is authoritative
      }
    }
    return event;
  }

  /** The task's status, from the terminal event. Null until one arrives. */
  get status() {
    return this.response ? this.response.status ?? null : null;
  }

  /** Whether the stream is missing any event, and which sequence numbers. */
  get sequence() {
    return checkSequence(this.events);
  }
}

/** Assemble the assistant text of a finished response object. */
export function outputText(response) {
  if (!response || !Array.isArray(response.output)) return '';
  return response.output
    .filter((item) => item && item.type === 'message')
    .flatMap((item) => (Array.isArray(item.content) ? item.content : []))
    .filter((part) => part && part.type === 'output_text')
    .map((part) => part.text ?? '')
    .join('');
}

/** Every artifact citation on a finished response, flattened out of the message annotations. */
export function artifacts(response) {
  if (!response || !Array.isArray(response.output)) return [];
  return response.output
    .filter((item) => item && item.type === 'message')
    .flatMap((item) => (Array.isArray(item.content) ? item.content : []))
    .flatMap((part) => (Array.isArray(part.annotations) ? part.annotations : []))
    .filter((a) => a && a.type === 'container_file_citation');
}

/**
 * A fresh idempotency key.
 *
 * Every retry of `POST /v1/responses` must carry one. Without it a retry after a timeout runs
 * the task a second time — and the first may still be running, editing the same files.
 */
export function idempotencyKey(prefix = 'uhp') {
  const uuid =
    globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function'
      ? globalThis.crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
  return `${prefix}-${uuid}`;
}

/**
 * Backoff delay in milliseconds for a given attempt, with full jitter.
 *
 * `retryAfterSeconds` — from a `Retry-After` header — wins when the server sent one, because a
 * server that told you when to come back knows more than your exponent does.
 */
export function backoffMs(attempt, { baseMs = 500, capMs = 30_000, retryAfterSeconds = null } = {}) {
  if (typeof retryAfterSeconds === 'number' && Number.isFinite(retryAfterSeconds)) {
    return Math.max(0, retryAfterSeconds * 1000);
  }
  const ceiling = Math.min(capMs, baseMs * 2 ** Math.max(0, attempt));
  return Math.floor(Math.random() * ceiling);
}

/** Whether this failure is worth another attempt. Re-exported so a client needs one import. */
export { isRetryable, checkSequence };

export default {
  SseDecoder,
  readEventStream,
  TaskAccumulator,
  outputText,
  artifacts,
  idempotencyKey,
  backoffMs,
  isRetryable,
  checkSequence,
};
